    %indvar1.lcssa
    %indvar2

DEPENDENCY CHAIN (source):
    %indvar2 = phi i32 [ 1, %entry ], [ %indvar3, %for.inc ]
    %indvar3 = phi i32 [ 0, %entry ], [ %inc, %for.inc ]
    %inc = add i32 %indvar3, 1
    %exitcond = icmp eq i32 %indvar3, 2

